        case when CREATED_BY_REFERENCE is not null or TASK_REMARKS is not null or SLA_REFERENCE is not null or OWNING_TEAM_NAME is not null
             then md5(upper(coalesce(CREATED_BY_REFERENCE::varchar,'') || '||' || coalesce(TASK_REMARKS::varchar,'') || '||' || coalesce(SLA_REFERENCE::varchar,'') || '||' || coalesce(OWNING_TEAM_NAME::varchar,'')))
